import assert from 'node:assert/strict';
import { createFeed } from './src/tenant-event-feed/index.mjs';
import { createRouter } from './src/layered-routing/index.mjs';
import { ExpiringStore } from './src/tenant-cache/store.mjs';
import { TenantCache } from './src/tenant-cache/cache.mjs';

const feed = createFeed();
const input = { type: 'created', payload: { nested: { value: 1 } } };
const [published] = feed.publishBatch('red', [input]);
input.payload.nested.value = 99;
published.payload.nested.value = 98;
assert.equal(feed.history('red')[0].payload.nested.value, 1);
const deliveries = [];
feed.subscribe('red', 0, record => { record.payload.nested.value = -1; deliveries.push(record); });
feed.subscribe('red', 0, record => deliveries.push(record));
feed.subscribe('blue', 0, () => assert.fail('cross-tenant delivery'));
assert.throws(() => feed.publishBatch('red', [
  { type: 'ok', payload: {} },
  { type: '', payload: {} },
]));
assert.deepEqual(feed.history('red').map(r => r.sequence), [1]);
const [next] = feed.publishBatch('red', [{ type: 'created', payload: { nested: { value: 2 } } }]);
assert.equal(next.sequence, 2);
assert.equal(deliveries[0].payload.nested.value, -1);
assert.equal(deliveries[1].payload.nested.value, 2);
assert.deepEqual(feed.history('red').map(r => r.sequence), [1, 2]);
assert.equal(feed.publishBatch('blue', [])[0], undefined);

const routeInput = { defaults: { enabled: true, timeout: 5, label: 'default', headers: { a: 'one', b: 'two' } },
  routes: [
    { id: 'wild', pattern: '*', settings: { target: 'wild' } },
    { id: 'prefix', pattern: '/app/*', settings: { enabled: false, timeout: 0, label: '' } },
    { id: 'same-first', pattern: '/app/x/*', settings: { target: 'first' } },
    { id: 'same-second', pattern: '/app/x/*', settings: { target: 'second' } },
    { id: 'exact', pattern: '/app', settings: { target: 'exact' } },
  ] };
const router = createRouter(routeInput);
routeInput.routes[1].settings.enabled = true;
router.setTenant('red', { headers: { b: null, c: '' }, label: '' });
const tenantInput = { enabled: true };
router.setTenant('blue', tenantInput);
tenantInput.enabled = false;
assert.equal(router.resolve('red', '/app').route, 'exact');
const app = router.resolve('red', '/app/file');
assert.equal(app.route, 'prefix');
assert.equal(app.enabled, false);
assert.equal(app.timeout, 0);
assert.equal(app.label, '');
assert.deepEqual(app.headers, { a: 'one', c: '' });
app.headers.a = 'mutated';
assert.equal(router.resolve('red', '/app/file').headers.a, 'one');
assert.equal(router.resolve('red', '/app/x/y').target, 'first');
assert.equal(router.resolve('red', '/apple').route, 'wild');
assert.equal(router.resolve('red', '/missing').route, 'wild');
router.setTenant('red', { enabled: true });
assert.equal(router.resolve('red', '/app/file').enabled, true);
assert.equal(router.resolve('blue', '/app/file').enabled, false);

let now = 100;
const cache = new TenantCache(new ExpiringStore({ now: () => now }));
let loads = 0;
assert.equal(await cache.getOrLoad('a:b', 'c', async () => { loads++; return 0; }, 10), 0);
assert.equal(await cache.getOrLoad('a', 'b:c', async () => { loads++; return false; }, 10), false);
assert.equal(await cache.getOrLoad('a:b', 'c', async () => { loads++; return 5; }, 10), 0);
assert.equal(loads, 2);
now = 110;
assert.equal(await cache.getOrLoad('a:b', 'c', async () => { loads++; return 3; }, 10), 3);
assert.equal(loads, 3);
console.log('additional contract checks passed');
