import { patternScore } from './pattern-score.mjs';
export function matchRoute(routes, path) {
  let bestRoute = null;
  let bestScore = -1;
  for (const route of routes) {
    const score = patternScore(route.pattern, path);
    if (score > bestScore) {
      bestRoute = route;
      bestScore = score;
    }
  }
  return bestRoute;
}

